beforeExample:
public class MyClass {
    public void foo(String s) {
        // Original code with fully qualified static method call
        java.util.Objects.requireNonNull(s, "String must not be null");
        System.out.println("Length: " + s.length());
    }

    public void bar(Object o) {
        // Example with another argument type
        java.util.Objects.requireNonNull(o);
    }
}

afterExample:
import static java.util.Objects.requireNonNull;

public class MyClass {
    public void foo(String s) {
        // Transformed code using simple name after static import
        requireNonNull(s, "String must not be null");
        System.out.println("Length: " + s.length());
    }

    public void bar(Object o) {
        // Example with another argument type
        requireNonNull(o);
    }
}

